<body>
<div class="container">
    <div class="hero">
        <h1>Welcome to MapleSure SponsorConnect</h1>
        <p>Your gateway to seamless claim submissions.</p>
        <button onclick="navigateToSecureSignIn()">Sign in securely</button>
    </div>

    <form id="claim-form">
        <div class="form-group">
            <label for="policy-number">Policy Number</label>
            <input type="text" id="policy-number">
        </div>
        <div class="form-group">
            <label for="member-id">Member ID</label>
            <input type="text" id="member-id">
        </div>
        <button type="button" onclick="lookUpMember()">Look up member</button>

        <div id="member-details" class="form-group" style="display:none;">
            <h4>Member Details:</h4>
            <p id="member-info"></p>
        </div>

        <div class="form-group">
            <label for="last-day-worked">Last Day Worked</label>
            <input type="date" id="last-day-worked">
        </div>
        <div class="form-group">
            <label for="first-day-absent">First Day Absent</label>
            <input type="date" id="first-day-absent">
        </div>
        <div class="form-group">
            <label for="nature-of-absence">Nature of Absence</label>
            <select id="nature-of-absence">
                <option value="sick">Sick Leave</option>
                <option value="vacation">Vacation</option>
                <option value="other">Other</option>
            </select>
        </div>
        <div class="form-group">
            <label for="details">Details</label>
            <textarea id="details" rows="4"></textarea>
        </div>
        <div class="form-group">
            <label for="documents">Upload Documents</label>
            <input type="file" id="documents" multiple onchange="updateFileList()">
            <div id="chosen-files"></div>
        </div>
        <button type="submit">Submit Claim</button>
    </form>

    <div id="confirmation">
        <h2>Claim Submitted</h2>
        <p>Your reference number is <span id="reference-number"></span>.</p>
        <p>Status: Received</p>
    </div>

    <footer>
        MapleSure Insurance — fictional demo application
    </footer>
</div>

<script>
    const mockData = {
        '12345': 'John Doe, Date of Birth: 1985-06-15, Address: 123 Maple St., Hometown',
        '67890': 'Jane Smith, Date of Birth: 1990-02-20, Address: 456 Oak St., Hometown'
    };

    function navigateToSecureSignIn() {
        alert('Redirecting to secure sign-in...');
        window.location.href = '#'; // Replace with actual sign-in URL
    }

    function lookUpMember() {
        const memberId = document.getElementById('member-id').value;
        const memberInfo = mockData[memberId] || 'Member not found.';
        document.getElementById('member-info').innerText = memberInfo;
        document.getElementById('member-details').style.display = 'block';
    }

    function updateFileList() {
        const input = document.getElementById('documents');
        const fileList = document.getElementById('chosen-files');
        fileList.innerHTML = '';
        for (let i = 0; i < input.files.length; i++) {
            const li = document.createElement('li');
            li.textContent = input.files[i].name;
            fileList.appendChild(li);
        }
    }

    document.getElementById('claim-form').addEventListener('submit', function(event) {
        event.preventDefault();
        const confirmation = document.getElementById('confirmation');
        const referenceNumber = 'MS-2026-08-' + Math.floor(Math.random() * 9000 + 1000);
        document.getElementById('reference-number').innerText = referenceNumber;
        document.getElementById('claim-form').style.display = 'none';
        confirmation.style.display = 'block';
    });
</script>

</body>
